#include <fstream>
#include <mutex>
#include <stdexcept>
#include <string>
#include <vector>

std::mutex log_mutex;

std::vector<std::string> read_lines(const std::string& path) {
    std::ifstream in(path);                        // acquires the file.
    if (!in) throw std::runtime_error("cannot open " + path);
    std::vector<std::string> lines;                // owns its buffer.
    for (std::string line; std::getline(in, line);) {
        if (line == "STOP") return lines;          // early return: file still closed.
        lines.push_back(line);                     // may throw bad_alloc: still closed.
    }
    return lines;
}                                                  // ~ifstream closes on EVERY exit.

void append_log(const std::string& msg) {
    std::lock_guard<std::mutex> lock(log_mutex);   // locks now...
    std::ofstream out("app.log", std::ios::app);
    out << msg << '\n';
}                                                  // ...unlocks here, always.
